using System.IO;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;
using UnityEngine;

namespace Hollowmere.EditorTools
{
    /// <summary>
    /// Loads the village &amp; house design pack (docs/design/, generated by tools/housegen/) into the plain classes in
    /// DesignSpecs.cs. Builders (M1.6 P2 onward) read the houses and the village from here; DesignChecks validates them.
    /// Loading is strict: a JSON key with no matching field is an error, so a housegen schema change can't be lost.
    /// </summary>
    public static class DesignData
    {
        public const int HouseCount = 15;

        static readonly JsonSerializerSettings Settings = new JsonSerializerSettings
        {
            ContractResolver = new DefaultContractResolver { NamingStrategy = new SnakeCaseNamingStrategy() },
            MissingMemberHandling = MissingMemberHandling.Error,
        };

        /// <summary>Absolute path of docs/design (the project root is the folder above Assets).</summary>
        public static string Root => Path.GetFullPath(Path.Combine(Application.dataPath, "..", "docs", "design"));

        public static string HousePath(string slug) => Path.Combine(Root, "houses", slug + ".json");
        public static string VillagePath => Path.Combine(Root, "village.json");
        public static string CatalogPath => Path.Combine(Root, "asset_catalog.json");

        public static string Slug(int index) => "H" + index.ToString("00");

        public static HouseSpec LoadHouse(string slug) => LoadFile<HouseSpec>(HousePath(slug));

        public static HouseSpec LoadHouse(int index) => LoadHouse(Slug(index));

        /// <summary>All houses, H00..H14, in HouseCatalog order.</summary>
        public static HouseSpec[] LoadHouses() => Enumerable.Range(0, HouseCount).Select(i => LoadHouse(i)).ToArray();

        public static VillageSpec LoadVillage() => LoadFile<VillageSpec>(VillagePath);

        public static AssetCatalogSpec LoadCatalog() => LoadFile<AssetCatalogSpec>(CatalogPath);

        public static T LoadFile<T>(string path) where T : class
        {
            if (!File.Exists(path))
                throw new FileNotFoundException($"Design data missing: {path}. It is generated by tools/housegen/gen_docs.py.", path);
            return Parse<T>(File.ReadAllText(path), path);
        }

        /// <summary>Parses design JSON; any problem becomes an InvalidDataException naming the source.</summary>
        public static T Parse<T>(string json, string source = "json") where T : class
        {
            T result;
            try
            {
                result = JsonConvert.DeserializeObject<T>(json, Settings);
            }
            catch (JsonException e)
            {
                throw new InvalidDataException($"{source}: {e.Message}", e);
            }
            if (result == null) throw new InvalidDataException($"{source}: empty JSON");
            return result;
        }
    }
}
